<?php
declare(strict_types=1);namespace App\Controllers;use App\Exceptions\NotFoundException;use App\Support\{Request,Response};
final class KycController extends Controller {private function user():array{return app('users')->find((int)$_SESSION['user_id']);}
 public function index(Request $r):Response{$u=$this->user();$config=app('kyc')->configuration(country()->country);$submission=app('kyc')->current((int)$u['id'],country()->country);return $this->view('kyc.index',['title'=>'Identity verification','required'=>app('kyc')->required(country()->country),'config'=>$config,'submission'=>$submission,'fields'=>$config?app('forms')->definition($config['form_id']?(int)$config['form_id']:null):[],'documents'=>$submission?app('kyc')->documents((int)$submission['id']):[]],'layouts.dashboard');}
 public function save(Request $r):Response{try{$files=$r->files();$submission=app('kyc')->save($this->user(),country()->country,$r->all(),$files,$r->input('submit')==='1');foreach($files as$key=>$file)if(is_array($file)&&($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK)app('kyc')->document((int)$submission['id'],$key,$file);$this->flash('success',$r->input('submit')==='1'?'Identity verification submitted.':'Draft saved.');}catch(\Throwable $e){$this->flash('error',$e->getMessage());}return $this->redirect('dashboard.kyc');}
 public function document(Request $r):Response{$doc=app('database')?->one('SELECT d.*,s.user_id FROM kyc_documents d JOIN kyc_submissions s ON s.id=d.kyc_submission_id WHERE d.id=?',[(int)$r->route('document')]);if(!$doc||(int)$doc['user_id']!==(int)$this->user()['id'])throw new NotFoundException('Document not found.');return app(MediaController::class)->privateFile((string)$doc['storage_path'],(string)$doc['original_filename'],(string)$doc['mime_type']);}}
